INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-art_blender-as289', 'stk-art_blender', 'AS 289', 'doc', '{"docs": [{"id": "stk-dr-m172447", "n": "Dr. Ali Duman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 192 (ترم كورونا) - AS289\nملاحظة: ترم 192 كان نصفه حضور ونصفه اونلاين\n\nالتحضير : شديد في الاونلاين وفي الحضور يحضر بداية الكلاس واللي يتأخر ياخذ ليت.\nطريقة الشرح : شرحه سيء أشبه بالتلقين ويفترض إن عندك قدرة عالية على الفهم.\nالكويزات : في الحضور كان عنده كويز كل اسبوع عن ماتيريال الاسبوع اللي قبله وكانت كويزاته سهلة والوقت كويس. في الاونلاين تحول الميجر الثاني والفاينال إلى كويزات اونلاين وكانت كويزات جحيم بمعنى الكلمة كان الكويز ثلاث أسئلة (السؤال عليه 3.3% من الكورس) والوقت قصير ومهما ذاكرت ما يمديك تحل الثلاثة كلهم (أقول هالكلام وأنا طالب أونر)، اللي مذاكر كويس يحل سؤال أو سؤالين.\nالمياجر: اختبرنا الميجر الأول حضور وكان سهل إلى متوسط أما الثاني فتحول إلى كويزات أونلاين (شوف تقييم الكويزات).\nالفاينلات : ما اظن احد اختبر فاينال معاه لأنه كان يهدد اللي ياخذ IC (اللي ما يبي NP ويبي قريد طبيعي لازم يطلب IC اللي هي قريد غير مكتمل ويختبر الفاينال في الصيف) هددهم بإن الفاينال بيكون أصعب بكثير بحجة إن أغلب الدرجات جاية من اختبارات أونلاين (بس ما أصدقه لأني ما أظن إنو في أسئلة أصعب من كوزاته الأونلاين أصلا).\nالقريد النهائي: أقيمه بالحضور C وبالاونلاين FFFFF. أنا أخذت NP (نجاح بدون قريد).\nالصوت: في الحضور كان الصوت ضعيف والافضل تجلس قدام بس في الاونلاين كان كويس.\nإضافات : الدكتور تعامله سيء وما يقدر حقوق الطلاب نهائيا. من حق الطلاب إنهم ياخذو المادة IC لكنه صعب المادة وخلا الNP (نجاح بدون قريد) فيها بمستوى الB+ عالأقل عشان محد ياخذ IC وفوقها جلس يهدد اللي ياخذ IC. في أحد الكلاسات ظهر ايميل على الشاشة من شركة طيران، ما قريته بس واضح ليش ما يبي احد ياخذ IC. وكذلك ما يقدر ظروف الطلاب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1524198-as289", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-duman/172447/9", "user": "Art_Blender", "ts": 1595704763000, "tid": 172447, "pn": 9}}]}', 1595704763000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
